INSERT INTO public."GameQuestions" VALUES ('bf0ae4c6-6877-455f-ab0a-0016baa7519c', 'რომ შეგეძლოს ნებისმიერ ცნობილ ადამიანთან ვახშამი, ვის აირჩევდი?', '["\u10D3\u10D8\u10D3 \u10DB\u10DD\u10D0\u10D6\u10E0\u10DD\u10D5\u10DC\u10D4\u10E1 \u10D0\u10DC \u10DB\u10D4\u10EA\u10DC\u10D8\u10D4\u10E0\u10E1","\u10E1\u10D0\u10E7\u10D5\u10D0\u10E0\u10D4\u10DA \u10DB\u10E3\u10E1\u10D8\u10D9\u10DD\u10E1\u10E1 \u10D0\u10DC \u10DB\u10E1\u10D0\u10EE\u10D8\u10DD\u10D1\u10E1","\u10D7\u10D0\u10DC\u10D0\u10DB\u10D4\u10D3\u10E0\u10DD\u10D5\u10D4 \u10D8\u10DC\u10DD\u10D5\u10D0\u10E2\u10DD\u10E0\u10E1","\u10D8\u10E1\u10E2\u10DD\u10E0\u10D8\u10E3\u10DA \u10DE\u10D8\u10E0\u10DD\u10D5\u10DC\u10D4\u10D1\u10D0\u10E1"]', 'fun', true, 1, '2026-10-04 08:30:19.810823+00', '2026-10-04 08:30:19.810823+00') ON CONFLICT DO NOTHING;
INSERT INTO public."GameQuestions" VALUES ('c8e072ad-2357-417c-87d8-e291b7dc037a', 'რა ჟანრის ფილმს უყურებდით საღამოს ერთად?', '["\u10DB\u10E1\u10E3\u10D1\u10E3\u10E5 \u10E0\u10DD\u10DB\u10D0\u10DC\u10E2\u10D8\u10D9\u10E3\u10DA \u10D9\u10DD\u10DB\u10D4\u10D3\u10D8\u10D0\u10E1","\u10E9\u10D0\u10DB\u10D7\u10E0\u10D4\u10D5 \u10E4\u10E1\u10D8\u10E5\u10DD\u10DA\u10DD\u10D2\u10D8\u10E3\u10E0 \u10D7\u10E0\u10D8\u10DA\u10D4\u10E0\u10E1","\u10E1\u10D0\u10DB\u10D4\u10EA\u10DC\u10D8\u10D4\u10E0\u10DD \u10E4\u10D0\u10DC\u10E2\u10D0\u10E1\u10E2\u10D8\u10D9\u10D0\u10E1","\u10D3\u10E0\u10D0\u10DB\u10D0\u10E2\u10E3\u10DA \u10D3\u10D0 \u10D4\u10DB\u10DD\u10EA\u10D8\u10E3\u10E0 \u10D8\u10E1\u10E2\u10DD\u10E0\u10D8\u10D0\u10E1"]', 'entertainment', true, 1, '2026-10-04 08:30:19.810823+00', '2026-10-04 08:30:19.810823+00') ON CONFLICT DO NOTHING;
